CREATE TABLE o_t (k INTEGER, s TEXT)
INSERT INTO o_t VALUES (3, 'b'), (1, NULL), (2, 'a'), (2, 'c'), (NULL, 'a'), (3, NULL)
SELECT k AS k, s AS s FROM o_t ORDER BY k, s
SELECT k AS k, s AS s FROM o_t ORDER BY k DESC, s ASC
SELECT k AS k, s AS s FROM o_t ORDER BY k DESC, s DESC
SELECT k AS k FROM o_t ORDER BY k LIMIT 2
SELECT k AS k, s AS s FROM o_t ORDER BY k, s LIMIT 2 OFFSET 2
SELECT k AS k, s AS s FROM o_t ORDER BY s DESC, k LIMIT 3 OFFSET 1
SELECT DISTINCT s AS s FROM o_t ORDER BY s
SELECT DISTINCT k AS k, s AS s FROM o_t ORDER BY k, s
SELECT k AS k FROM o_t ORDER BY k LIMIT 0
SELECT k AS k FROM o_t ORDER BY k LIMIT 100 OFFSET 4
SELECT k AS kk, s AS ss FROM o_t ORDER BY kk DESC, ss LIMIT 1
SELECT k FROM o_t ORDER BY k
SELECT s FROM o_t WHERE k > 1 ORDER BY s
SELECT DISTINCT k AS k FROM o_t ORDER BY k DESC
SELECT k AS k, s AS s FROM o_t WHERE s IS NOT NULL ORDER BY s DESC, k DESC LIMIT 2 OFFSET 1
SELECT k AS k FROM o_t ORDER BY k OFFSET 5
